import { Box, TextField, Typography, Button, FormGroup, FormControlLabel, Checkbox, CircularProgress } from "@mui/material";
import axios from "axios";
import { useState } from "react";

export default function Login() {
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [emailError, setEmailError] = useState("");
    const [passwordError, setPasswordError] = useState("");
    const [loginError, setLoginError] = useState("");

    const handleLogin = () => {
        setLoading(!loading);
    };

    return (
        <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            height="100vh"
            width="100vw"
            margin="0"
            padding="0"
            position="fixed"
            top="0"
            left="0"
            bgcolor="whitesmoke"
        >
            <Box
                bgcolor="white"
                borderRadius="8px"
                padding="40px"
                boxShadow="0 0 10px rgba(0, 0, 0, 0.2)"
                textAlign="center"
                width="90%"
                maxWidth="400px"
                style={{
                    backdropFilter: "blur(10px)",
                    WebkitBackdropFilter: "blur(10px)",
                }}
            >
                <Typography fontWeight="bold" fontSize="25px" mb="30px" color="black">
                    VSpaceへログイン
                </Typography>
                <TextField
                    id="email"
                    label="Email"
                    variant="outlined"
                    fullWidth
                    style={{ marginBottom: "15px" }}
                    onChange={event => setEmail(event.target.value)}
                />
                <TextField
                    id="password"
                    label="Password"
                    variant="outlined"
                    type="password"
                    fullWidth
                    style={{ marginBottom: "15px" }}
                    onChange={event => setEmail(event.target.value)}
                />
                <FormGroup style={{ marginBottom: "15px" }}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                sx={{
                                    color: "black",
                                    '&.Mui-checked': {
                                        color: "black"
                                    },
                                }}
                            />
                        }
                        label="自動ログイン"
                    />
                </FormGroup>
                <Box>
                    <Button
                        variant="contained"
                        fullWidth
                        style={{ padding: "15px", backgroundColor: "black", color: "white" }}
                        onClick={handleLogin}
                    >
                        ログイン
                        {loading && (
                            <Box position="absolute" display="flex" justifyContent="center" alignItems="center" width="50%" height="50%" bgcolor="black">
                                <CircularProgress size="20px" style={{ color: "white" }} />
                            </Box>
                        )}
                    </Button>
                </Box>
            </Box>
        </Box>
    );
}
